const sqlite = require('./sqlite');
const path = require('path');
const apiBible = require('./apiBible');
const aiVerse = require('./aiVerse');
const { EventEmitter } = require('events');

// 'lateVerse': an AI translation confirmed after the live answer was given
// (server.js forwards it to the operator's queue)
const events = new EventEmitter();

const DB_PATH = require('./paths').BIBLE_DB;
let db;

function getDb() {
  if (!db) {
    db = sqlite.open(DB_PATH);
    db.pragma('journal_mode = WAL');
    initSchema();
    // Earlier versions cached verse text generated by an AI model. That is
    // not scripture and must never reach the screen.
    const removed = db.prepare(`DELETE FROM verses WHERE source = 'claude_cache'`).run().changes;
    if (removed) console.log(`[Bible] Removed ${removed} AI-generated verses from the local database`);
  }
  return db;
}

function initSchema() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS verses (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      translation TEXT NOT NULL,
      book        TEXT NOT NULL,
      book_num    INTEGER NOT NULL,
      chapter     INTEGER NOT NULL,
      verse       INTEGER NOT NULL,
      verse_end   INTEGER NOT NULL DEFAULT 0,
      text        TEXT NOT NULL,
      source      TEXT DEFAULT 'seed'
    );
    CREATE INDEX IF NOT EXISTS idx_lookup
      ON verses(translation, book_num, chapter, verse);

    -- Translations in the local library (services/library.js): where each
    -- came from, its licence and what it covers
    CREATE TABLE IF NOT EXISTS translation_meta (
      code         TEXT PRIMARY KEY,
      name         TEXT NOT NULL,
      source       TEXT,
      licence      TEXT,
      coverage     TEXT,
      verses       INTEGER,
      books        INTEGER,
      missing      INTEGER,
      installed_at TEXT,
      note         TEXT
    );

    CREATE TABLE IF NOT EXISTS bible_structure (
      book_num  INTEGER NOT NULL,
      book      TEXT NOT NULL,
      chapter   INTEGER NOT NULL,
      max_verse INTEGER NOT NULL,
      PRIMARY KEY (book_num, chapter)
    );
  `);
  // Upgrade databases created before range-block imports. Existing records
  // remain single verses because a zero verse_end is interpreted as verse.
  const verseColumns = new Set(db.prepare('PRAGMA table_info(verses)').all().map(column => column.name));
  if (!verseColumns.has('verse_end')) {
    try {
      db.exec('ALTER TABLE verses ADD COLUMN verse_end INTEGER NOT NULL DEFAULT 0');
    } catch (error) {
      // Test workers or two app processes may race to apply the same migration.
      const refreshedColumns = new Set(db.prepare('PRAGMA table_info(verses)').all().map(column => column.name));
      if (!refreshedColumns.has('verse_end')) throw error;
    }
  }
}

// Translations stored in bible.db by `npm run seed` (all public domain)
const LOCAL_TRANSLATIONS = {
  KJV: 'King James Version',
  ASV: 'American Standard Version (1901)',
  YLT: "Young's Literal Translation",
  BBE: 'Bible in Basic English',
};

// Display names for licensed translations served through API.Bible
const LICENSED_NAMES = {
  NKJV: 'New King James Version', AMP: 'Amplified Bible', AMPC: 'Amplified Bible, Classic',
  TPT: 'The Passion Translation', MSG: 'The Message', GNT: 'Good News Translation',
  TLB: 'The Living Bible', NIV: 'New International Version', ESV: 'English Standard Version',
  NLT: 'New Living Translation', NASB: 'New American Standard Bible', CSB: 'Christian Standard Bible',
  CEV: 'Contemporary English Version', NCV: 'New Century Version', HCSB: 'Holman Christian Standard Bible',
  WEB: 'World English Bible', NRSV: 'New Revised Standard Version', RSV: 'Revised Standard Version',
};

// Local translations: the four from `npm run seed` plus whatever the library
// installed or imported (translation_meta). Cached; library.js invalidates it.
let localCache = null;
function localTranslations() {
  if (localCache) return localCache;
  const map = { ...LOCAL_TRANSLATIONS };
  for (const m of getDb().prepare('SELECT code, name FROM translation_meta').all()) map[m.code] = m.name;
  return (localCache = map);
}
function invalidateTranslations() { localCache = null; }

function localCounts() {
  // AI beta cache rows are experimental wording, not installed Bible text.
  // Never let an old AI paraphrase make a licensed edition look installed.
  const rows = getDb().prepare(`SELECT translation, COUNT(*) AS c FROM verses
    WHERE COALESCE(substr(source, 1, 3), '') != 'ai_' GROUP BY translation`).all();
  return Object.fromEntries(rows.map(r => [r.translation, r.c]));
}

// What the operator can actually pick: local translations that are seeded,
// plus whatever the API.Bible key unlocks. Everything else is listed as
// unavailable with the reason, never faked.
async function listTranslations() {
  const counts = localCounts();
  const out = [];
  const local = localTranslations();
  const metaRows = Object.fromEntries(getDb().prepare('SELECT code, coverage FROM translation_meta').all().map(m => [m.code, m]));
  for (const [code, name] of Object.entries(local)) {
    const m = metaRows[code];
    const count = counts[code] || 0;
    // If a recognised licensed edition has only stale AI cache rows and no
    // real imported text, let the API.Bible catalogue decide its availability.
    if (m && count === 0 && LICENSED_NAMES[code]) continue;
    const ok = m ? count > 0 : count > 30000;
    const reason = ok ? null : m
      ? 'Translation is listed, but no verse text is stored. Import an authorised copy; npm run seed does not install this translation.'
      : 'Not downloaded yet — run npm run seed';
    out.push({ code, name, provider: 'local', available: ok, ...(m && m.coverage !== 'Full Bible' ? { coverage: m.coverage } : {}),
      ...(m && { installedVerses: count }), reason });
  }
  const remote = new Set(await apiBible.availableCodes());
  const st = apiBible.status();
  for (const [code, name] of Object.entries(LICENSED_NAMES)) {
    if (local[code] && (counts[code] || 0) > 0) continue; // real stored text takes precedence
    // A model-generated paraphrase is never the published wording of a named,
    // copyrighted edition. Only the publisher-licensed API or an imported local
    // copy may make one of these translations selectable.
    if (remote.has(code)) out.push({ code, name, provider: 'apibible', available: true, reason: null });
    else out.push({ code, name, provider: 'apibible', available: false,
      reason: !st.configured
        ? `${code} is a licensed edition. Add an API.Bible key with ${code} in its plan, or import an authorised ${code} file.`
        : `${code} is not included in your API.Bible plan. Import an authorised ${code} file or use a plan that includes it. AI-generated wording is not the published ${code} text.` });
  }
  for (const code of remote) {
    if (!local[code] && !LICENSED_NAMES[code]) out.push({ code, name: code, provider: 'apibible', available: true, reason: null });
  }
  return out;
}

// Saved AI answers (source ai_*) are looked up separately so licensed
// API.Bible text, once a key is added, takes precedence over them
function localVerse(book, chapter, verse, translation, { ai = false } = {}) {
  const row = getDb().prepare(`
    SELECT text, book, chapter, verse,
      COALESCE(NULLIF(verse_end, 0), verse) AS verse_end,
      translation, source
    FROM verses
    WHERE book = ? AND chapter = ? AND translation = ?
      AND verse <= ? AND COALESCE(NULLIF(verse_end, 0), verse) >= ?
      AND (substr(source, 1, 3) = 'ai_') = ?
    ORDER BY (COALESCE(NULLIF(verse_end, 0), verse) - verse) ASC, verse DESC
    LIMIT 1
  `).get(book, chapter, translation, verse, verse, ai ? 1 : 0);
  if (!row) return null;
  const verseEnd = Number(row.verse_end || row.verse);
  return {
    reference: `${row.book} ${row.chapter}:${row.verse}${verseEnd > row.verse ? `-${verseEnd}` : ''}`,
    translation: row.translation,
    text: row.text,
    book: row.book,
    chapter: row.chapter,
    verse: row.verse,
    ...(verseEnd > row.verse ? { verseEnd } : {}),
    source: row.source || 'local',
    ...(AI_NOTES[row.source] ? { verification: row.source.replace('ai_', ''), note: AI_NOTES[row.source] } : {})
  };
}

const AI_NOTES = {
  ai_verified: 'AI beta · matched by 2+ providers (saved)',
  ai_grounded: 'AI beta · web-searched (saved)',
};

// Confirmed AI answers are saved so the verse is instant and works offline
// next time. Unverified answers are never saved.
function saveAiVerse(v) {
  if (v.verification !== 'verified' && v.verification !== 'grounded') return;
  try {
    const db = getDb();
    db.prepare(`DELETE FROM verses WHERE translation = ? AND book = ? AND chapter = ? AND verse = ?`).run(v.translation, v.book, v.chapter, v.verse);
    db.prepare(`INSERT INTO verses (translation, book, book_num, chapter, verse, text, source) VALUES (?, ?, ?, ?, ?, ?, ?)`)
      .run(v.translation, v.book, getBookNum(v.book), v.chapter, v.verse, v.text, 'ai_' + v.verification);
  } catch (err) {
    console.error('[Bible] Could not save AI verse:', err.message);
  }
}

// ── Get verse — real text only: local DB, then API.Bible, then KJV with the reason ──
// opts.live: the operator is waiting — AI lookups answer within a few seconds
// and anything confirmed later is saved for next time
const LIVE_DEADLINE_MS = 4000;

async function getVerse(book, chapter, verse, translation = 'KJV', opts = {}) {
  translation = String(translation || 'KJV').toUpperCase();

  const local = localVerse(book, chapter, verse, translation);
  if (local) return local;

  let reason;
  const storedCount = localCounts()[translation] || 0;
  const localName = localTranslations()[translation];
  const registered = getDb().prepare('SELECT code FROM translation_meta WHERE code = ?').get(translation);
  if (localName && storedCount > 0) {
    reason = `${book} ${chapter}:${verse} is not part of the ${translation} text`;
  } else if (registered && !LICENSED_NAMES[translation]) {
    reason = `${translation} is registered but has no verse text stored. Import an authorised ${translation} archive; npm run seed does not install it.`;
  } else {
    const remote = await apiBible.getVerse(getBookNum(book), book, chapter, verse, translation);
    if (!remote.error) return remote;
    reason = remote.error;

    const savedAi = localVerse(book, chapter, verse, translation, { ai: true });
    if (savedAi && !LICENSED_NAMES[translation]) return savedAi;

    // Never substitute model-generated wording for a known licensed edition.
    // Even multiple models agreeing is not proof that the publisher's text was
    // used; the exact licensed text must come from API.Bible or a local import.
    if (LICENSED_NAMES[translation]) {
      reason = `${translation} is a licensed edition, but it is not available locally or in your API.Bible plan. Import an authorised copy or use a plan that includes it. Di.Verse will not invent the published wording.`;
    } else if (aiVerse.isAvailable()) {
      const kjvRow = localVerse(book, chapter, verse, 'KJV');
      const ai = await aiVerse.getVerse(book, chapter, verse, translation, kjvRow && kjvRow.text,
        opts.live ? { deadlineMs: LIVE_DEADLINE_MS, onLateResult: late => { saveAiVerse(late); events.emit('lateVerse', late); } } : {});
      // Experimental unlicensed translation lookups remain visibly marked AI
      // beta; only confirmed wording is cached.
      if (!ai.error && (ai.verification !== 'unverified' || opts.allowUnverified || process.env.AI_SHOW_UNVERIFIED === 'true')) { saveAiVerse(ai); return ai; }
      reason = ai.error || `${translation} wording could not be confirmed (${ai.note.replace(/^AI beta · /, '')})`;
    }
  }

  if (translation === 'KJV') return null;
  console.log(`[Bible] ${book} ${chapter}:${verse} (${translation}) unavailable: ${reason} — showing KJV`);
  const kjv = localVerse(book, chapter, verse, 'KJV');
  return kjv && Object.assign(kjv, { requestedTranslation: translation, fallback: true, fallbackReason: reason });
}

// Book number lookup
const BOOK_NUMS = {
  'Genesis':1,'Exodus':2,'Leviticus':3,'Numbers':4,'Deuteronomy':5,
  'Joshua':6,'Judges':7,'Ruth':8,'1 Samuel':9,'2 Samuel':10,
  '1 Kings':11,'2 Kings':12,'1 Chronicles':13,'2 Chronicles':14,
  'Ezra':15,'Nehemiah':16,'Esther':17,'Job':18,'Psalms':19,'Proverbs':20,
  'Ecclesiastes':21,'Song of Solomon':22,'Isaiah':23,'Jeremiah':24,
  'Lamentations':25,'Ezekiel':26,'Daniel':27,'Hosea':28,'Joel':29,
  'Amos':30,'Obadiah':31,'Jonah':32,'Micah':33,'Nahum':34,
  'Habakkuk':35,'Zephaniah':36,'Haggai':37,'Zechariah':38,'Malachi':39,
  'Matthew':40,'Mark':41,'Luke':42,'John':43,'Acts':44,'Romans':45,
  '1 Corinthians':46,'2 Corinthians':47,'Galatians':48,'Ephesians':49,
  'Philippians':50,'Colossians':51,'1 Thessalonians':52,'2 Thessalonians':53,
  '1 Timothy':54,'2 Timothy':55,'Titus':56,'Philemon':57,'Hebrews':58,
  'James':59,'1 Peter':60,'2 Peter':61,'1 John':62,'2 John':63,
  '3 John':64,'Jude':65,'Revelation':66
};

function getBookNum(book) {
  return BOOK_NUMS[book] || null;
}

function searchVerses(query, translation = 'KJV', limit = 10) {
  const db = getDb();
  return db.prepare(`
    SELECT book, chapter, verse, text, translation
    FROM verses
    WHERE translation = ? AND text LIKE ?
    LIMIT ?
  `).all(translation, `%${query}%`, limit);
}

// ── Passage: a range of verses in one chapter, e.g. John 3:16-18 ──
const SUPERSCRIPT = { 0:'⁰',1:'¹',2:'²',3:'³',4:'⁴',5:'⁵',6:'⁶',7:'⁷',8:'⁸',9:'⁹' };
const sup = n => String(n).split('').map(d => SUPERSCRIPT[d]).join('');
const VERIFY_RANK = { verified: 1, grounded: 2, unverified: 3 };

async function getPassage(book, chapter, verse, verseEnd, translation = 'KJV', opts = {}) {
  if (!verseEnd || verseEnd <= verse) return getVerse(book, chapter, verse, translation, opts);

  // Don't run past the end of the chapter
  const row = getDb().prepare(`SELECT max_verse FROM bible_structure WHERE book = ? AND chapter = ?`).get(book, chapter);
  const last = Math.min(verseEnd, row ? row.max_verse : verseEnd);
  if (last <= verse) return getVerse(book, chapter, verse, translation, opts);

  // A few at a time: fast for network-backed translations without bursting
  // past free-tier per-minute limits (3 AI providers per verse)
  const verses = [];
  for (let v = verse; v <= last; v++) verses.push(v);
  const results = new Array(verses.length);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(3, verses.length) }, async () => {
    while (next < verses.length) {
      const i = next++;
      results[i] = await getVerse(book, chapter, verses[i], translation, opts);
    }
  }));
  const found = results.filter(Boolean);
  if (!found.length) return null;
  const seenBlocks = new Set();
  const parts = found.filter(p => {
    const end = p.verseEnd || p.verse;
    const key = [p.translation, p.book, p.chapter, p.verse, end, p.source || '', p.fallback ? 'fallback' : 'local'].join('|');
    if (seenBlocks.has(key)) return false;
    seenBlocks.add(key);
    return true;
  }).sort((a, b) => a.verse - b.verse);

  const fallbacks = parts.filter(p => p.fallback);
  const worst = parts.filter(p => p.verification).sort((a, b) => VERIFY_RANK[b.verification] - VERIFY_RANK[a.verification])[0];
  const shownTranslations = [...new Set(parts.map(p => p.translation))];
  const firstVerse = parts[0].verse;
  const lastVerse = Math.max(...parts.map(p => p.verseEnd || p.verse));
  return {
    reference: `${book} ${chapter}:${firstVerse}${lastVerse > firstVerse ? `-${lastVerse}` : ''}`,
    translation: shownTranslations.join('/'),
    text: parts.map(p => {
      const end = p.verseEnd || p.verse;
      const marker = sup(p.verse) + (end > p.verse ? '–' + sup(end) : '');
      return marker + '\u2009' + p.text;
    }).join(' '),
    book, chapter, verse: firstVerse, verseEnd: lastVerse,
    source: parts[0].source,
    ...(fallbacks.length ? { fallback: true, requestedTranslation: String(translation).toUpperCase(),
      fallbackReason: `${fallbacks.length} of ${parts.length} verses: ${fallbacks[0].fallbackReason}` } : {}),
    ...(worst ? { verification: worst.verification, note: worst.note } : {}),
    ...(parts[0].copyright ? { copyright: parts[0].copyright } : {}),
  };
}

module.exports = { invalidateTranslations, localTranslations, getDb, getVerse, getPassage, searchVerses, getBookNum, listTranslations, events };